@using sv_476cf903f74646df95e0fbb1139ad30e.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<select class="form-select form-select-sm warehouse-selector"
        value="@WarehouseState.CurrentWarehouseId"
        @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseStateService.Warehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.CurrentWarehouseId = newId;
        }
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@using sv_476cf903f74646df95e0fbb1139ad30e.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<span class="badge @BadgeClass">@AlertService.CurrentLowStockCount</span>

@code {
    /// <summary>
    /// When true, this badge instance participates in polling (subscribes/unsubscribes).
    /// Sidebar badges can set this to false — they still receive updates via the event
    /// but don't control the polling lifecycle.
    /// </summary>
    [Parameter]
    public bool ControlsPolling { get; set; }

    private string BadgeClass => AlertService.CurrentLowStockCount switch
    {
        > 10 => "bg-danger",
        > 5 => "bg-warning text-dark",
        > 0 => "bg-info",
        _ => "bg-success"
    };

    protected override void OnInitialized()
    {
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
        if (ControlsPolling)
        {
            AlertService.Subscribe();
        }
    }

    private async Task HandleAlertDataChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
        if (ControlsPolling)
        {
            AlertService.Unsubscribe();
        }
    }
}

