@using sv_476cf903f74646df95e0fbb1139ad30e.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard — @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">@WarehouseState.CurrentWarehouseName</p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            Low-Stock Alerts
            <AlertBadge ControlsPolling="true" />
        </h5>
        <p class="card-text text-muted">
            Checking for items below minimum stock levels every 10 seconds.
        </p>
        <p class="card-text">
            <strong>@AlertService.CurrentLowStockCount</strong> item(s) currently below threshold
            at <em>@WarehouseState.CurrentWarehouseName</em>.
        </p>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
    }

    private void HandleStateChanged() => InvokeAsync(StateHasChanged);

    private async Task HandleAlertDataChanged() => await InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
    }
}

